import {
  createElement,
  type CSSProperties,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  useCallback,
  useRef,
} from "react";
import "./spotlight-surface.css";

export interface SpotlightSurfaceProps extends HTMLAttributes<HTMLElement> {
  as?: "article" | "button" | "div" | "span";
  /** 光晕颜色，通常传 rgba */
  spotlightColor?: string;
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

const DEFAULT_SPOTLIGHT = "rgba(47, 135, 171, 0.12)";

/**
 * 鼠标跟随光晕的卡片表面：指针在卡片上移动时，一层柔和径向光晕跟随指针位置。
 * 光晕用独立子元素承载，避免与卡片既有样式里的伪元素相互覆盖。
 */
export function SpotlightSurface({
  as = "div",
  spotlightColor = DEFAULT_SPOTLIGHT,
  children,
  className,
  style,
  onMouseMove,
  ...rest
}: SpotlightSurfaceProps) {
  const hostRef = useRef<HTMLElement | null>(null);

  const handleMouseMove = useCallback(
    (event: MouseEvent<HTMLElement>) => {
      onMouseMove?.(event);
      const host = hostRef.current;
      if (!host) return;
      const rect = host.getBoundingClientRect();
      host.style.setProperty("--spotlight-x", `${event.clientX - rect.left}px`);
      host.style.setProperty("--spotlight-y", `${event.clientY - rect.top}px`);
    },
    [onMouseMove],
  );

  const surfaceStyle = {
    ...style,
    "--spotlight-color": spotlightColor,
  } as CSSProperties;

  return createElement(
    as,
    {
      ...rest,
      ref: hostRef,
      className: ["spotlight-surface", className].filter(Boolean).join(" "),
      style: surfaceStyle,
      onMouseMove: handleMouseMove,
    },
    <span
      key="spotlight-glow"
      className="spotlight-surface__glow"
      aria-hidden="true"
    />,
    children,
  );
}

export default SpotlightSurface;
